body?: {
// New text for the thread's first comment. Only its author can change it. `mentions` replaces who it names; omit it to keep them. An edit by a teammate notifies only the people it newly names who can read the thread; it sends nothing to followers or the team channel, and an edit by anyone else notifies no one.
body?: string, // minLength: 1, maxLength: 16000
// Spacefast user ids to @mention. Each must be on the Space's team and able to open it; `GET /v1/spaces/{spaceId}/comments/mentionable` lists who qualifies. Mentioned people are notified.
// maxItems: 50
mentions?: Array<
string // minLength: 1, maxLength: 160
>,
spamCommentId?: string, // minLength: 1
status?: "open" | "archived" | "spam",
},
spaceId: string, // minLength: 1
threadId: string, // minLength: 1
}): Promise<unknown>;
```

