X-Spacefast-Continuation-Token?: string, // maxLength: 4096
body: {
comments?: { live?: "default" | "on" | "off", previews?: "default" | "on" | "off", spamFilter?: boolean },
// Return `effect` and change nothing.
dryRun?: boolean,
// The `revision` from your last read. A stale one gets 409 `space_share_changed` with the current Share.
expectedRevision: string, // minLength: 1
general?: {
// Turn public access off and remove every editable public rule while keeping parent-team access as set. Refused with 409 when a public rule this API can't change would keep anything open.
closeAllPublic?: true,
indexing?: "allowed" | "blocked",
// Shortcut for both switches: `public` turns public on; `parent_team` turns public off and the parent team on; `private` turns both off. Turning public off removes every public rule this API can change.
level?: "private" | "parent_team" | "public",
// Everyone in the parent team: view and comment. Independent of `public`.
parentTeam?: { on: boolean },
// Anyone on the web. Independent of `parentTeam`. `on: false` removes every public rule this API can change; rules from sf.jsonc stay, and `effective.anonymous` says what they keep open.
public?: { on: boolean, role?: "viewer" | "commenter" },
// With `level: public`: what anyone on the web may do. Default `viewer`.
role?: "viewer" | "commenter",
},
},
spaceId: string,
}): Promise<unknown>;
```

