context: string, // minLength: 1, maxLength: 2000
// The form the feedback is about, if there is one: the formId from your earlier Tally tool calls.
formId?: string,
// For source "user": the user's message word for word, in their language, then one short line in English on what it is about. For source "agent": a 2 to 3 line summary in English, for the Tally team, of where you got stuck or what Tally cannot do. Not a reply to the user, and not the details from context.
message: string, // minLength: 1, maxLength: 1000
// negative when something failed or Tally cannot do what was asked, including a documented limit. positive only for praise or something that worked notably well.
sentiment: "positive" | "negative",
// Use "user" only when the user themselves says something about Tally. Use "agent" for everything else, including a missing feature you hit while doing their request.
source: "user" | "agent",
}): Promise<{
// LLM context - not shown to users.
