}): Promise<{
// An assay order.
assay?: {
assayId?: string,
// Which assay the order is for. Null for some older orders placed in the web app.
assayType?: string | null,
assays?: { id?: string, name?: string }[],
// Whether cancelAssay would work right now.
cancellable?: boolean,
cost?: object | null,
createdAt?: string,
name?: string | null,
notes?: string | null,
// The lab running the order, e.g. adaptyv, ginkgo or aalpha.
